        'Authorization': f'Bearer {TOKEN}',
        'Content-Type':'application/json'
    }, method='POST')
    with urllib.request.urlopen(req) as resp:
        return json.loads(resp.read().decode())

# sdt_genome lookup
resp=post('/delta/tables/select', {
    'database':'enigma_coral',
