    vals=defaultdict(list)
    for r in cov_rows:
        name=r.get('sdt_genome_name')
        v=r.get('read_coverage_statistic_average_comment_cov80_average_coverage_after_trimming_highest_and_lowest_10_percent_count_unit')
        if name and v is not None:
            try:
                vals[name].append(float(v))
            except Exception:
                pass
    for name, vs in vals.items():
        if vs:
            coverage[name]=sum(vs)/len(vs)

print('names', names)
print('found_ids', len(name_to_id))
print('dates', name_to_date_by_name)
print('coverage', coverage)
