import os, json, urllib.request
from datetime import datetime
import pandas as pd

BASE='https://hub.berdl.kbase.us/apis/mcp'
TOKEN=os.environ['KB_AUTH_TOKEN']

# load genome table
path='ncbi_submission/genome_table_Template_GenomeBatch.xlsx'
df=pd.read_excel(path, sheet_name='Genome_data')
# use assembly_name as genome name
names=[n for n in df['assembly_name'].dropna().astype(str).tolist()]

# helper to post

def post(endpoint, payload):
    url=f'{BASE}{endpoint}'
    req=urllib.request.Request(url, data=json.dumps(payload).encode(), headers={
        'Authorization': f'Bearer {TOKEN}',
        'Content-Type':'application/json'
    }, method='POST')
    with urllib.request.urlopen(req) as resp:
        return json.loads(resp.read().decode())

# sdt_genome lookup
resp=post('/delta/tables/select', {
    'database':'enigma_coral',
    'table':'sdt_genome',
    'columns':[{'name':'sdt_genome_id'},{'name':'sdt_genome_name'}],
    'filters':[{'column':'sdt_genome_name','operator':'IN','value':names}],
    'limit':1000
})
rows=resp.get('data',[])
name_to_id={r['sdt_genome_name']: r['sdt_genome_id'] for r in rows}
ids=[r['sdt_genome_id'] for r in rows]

# process outputs for those genomes
proc_out=[]
if ids:
    resp=post('/delta/tables/select', {
        'database':'enigma_coral',
        'table':'sys_process_output',
        'columns':[{'name':'sys_process_id'},{'name':'sdt_genome_id'}],
        'filters':[{'column':'sdt_genome_id','operator':'IN','value':ids}],
        'limit':1000
    })
    proc_out=resp.get('data',[])

proc_ids=sorted({r['sys_process_id'] for r in proc_out if r.get('sys_process_id')})

# fetch processes
processes=[]
if proc_ids:
    resp=post('/delta/tables/select', {
        'database':'enigma_coral',
        'table':'sys_process',
        'columns':[{'name':'sys_process_id'},{'name':'process_sys_oterm_name'},{'name':'date_start'},{'name':'date_end'}],
        'filters':[{'column':'sys_process_id','operator':'IN','value':proc_ids}],
        'limit':1000
    })
    processes=resp.get('data',[])

proc_map={p['sys_process_id']: p for p in processes}

# choose assembly date per genome
name_to_date={}
for r in proc_out:
    pid=r.get('sys_process_id')
    gid=r.get('sdt_genome_id')
    if not pid or not gid:
        continue
    p=proc_map.get(pid)
    if not p:
        continue
    pname=(p.get('process_sys_oterm_name') or '')
    if 'assembly' not in pname.lower():
        continue
    date=p.get('date_end') or p.get('date_start')
    if not date:
        continue
    # pick latest date if multiple
    existing=name_to_date.get(gid)
    if not existing or date>existing:
        name_to_date[gid]=date

# map to genome names
name_to_date_by_name={}
for name, gid in name_to_id.items():
    if gid in name_to_date:
        name_to_date_by_name[name]=name_to_date[gid]

# coverage from ddt_brick0000508
coverage={}
if names:
    resp=post('/delta/tables/select', {
        'database':'enigma_coral',
        'table':'ddt_brick0000508',
        'columns':[
            {'name':'sdt_genome_name'},
            {'name':'read_coverage_statistic_average_comment_cov80_average_coverage_after_trimming_highest_and_lowest_10_percent_count_unit'}
        ],
        'filters':[{'column':'sdt_genome_name','operator':'IN','value':names}],
        'limit':1000
    })
    cov_rows=resp.get('data',[])
    from collections import defaultdict
    vals=defaultdict(list)
    for r in cov_rows:
        name=r.get('sdt_genome_name')
        v=r.get('read_coverage_statistic_average_comment_cov80_average_coverage_after_trimming_highest_and_lowest_10_percent_count_unit')
        if name and v is not None:
            try:
                vals[name].append(float(v))
            except Exception:
                pass
    for name, vs in vals.items():
        if vs:
            coverage[name]=sum(vs)/len(vs)

print('names', names)
print('found_ids', len(name_to_id))
print('dates', name_to_date_by_name)
print('coverage', coverage)
